parameters.query:
=UPDATE manuscript_versions
SET file_url = '{{ $json.fileUrl }}'
WHERE manuscript_id = '{{ $json.manuscriptId }}'
  AND phase_number = {{ $json.phaseNumber }}
  AND version_type = 'approved_snapshot'
RETURNING id, file_url;

parameters.jsCode:
const webhookData = $('Webhook').first().json.body;
const manuscriptData = $('Fetch Manuscript Content').first().json;

return {
  json: {
    manuscript_id: webhookData.manuscriptId,
    phase_number: webhookData.phaseNumber,
    editor_name: webhookData.editorName,
    full_content: manuscriptData.full_content,
    word_count: manuscriptData.full_content.split(/\s+/).filter(w => w.length > 0).length
  }
};

const webhookData = $('Webhook').first().json.body;
const manuscriptData = $('Fetch Manuscript Content').first().json;
const authorData = $('Fetch Author Email').first().json; // If you have this node

// Format the manuscript content as HTML
// Assuming chapters are separated by "---" or similar
let chapters = manuscriptData.full_content.split(/\n---\n/);

// Build HTML content
let htmlContent = '';

chapters.forEach((chapter, index) => {
  // Extract chapter title if it exists (first line)
  const lines = chapter.trim().split('\n');
  const firstLine = lines[0];

  // Check if first line looks like a chapter title (short, all caps, or starts with "Chapter")
  const isChapterTitle = firstLine.length < 50 && 
    (firstLine.toUpperCase() === firstLine || firstLine.startsWith('Chapter') || firstLine.startsWith('CHAPTER'));

  if (isChapterTitle) {
    htmlContent += `<h1>${firstLine}</h1>\n`;
    // Rest of the chapter
    const chapterBody = lines.slice(1).join('\n');
    const paragraphs = chapterBody.split('\n\n');
    paragraphs.forEach(para => {
      if (para.trim()) {
        htmlContent += `<p>${para.trim()}</p>\n`;
      }
    });
  } else {
    // No clear title, just use "Chapter X"
    htmlContent += `<h1>Chapter ${index + 1}</h1>\n`;
    const paragraphs = chapter.split('\n\n');
    paragraphs.forEach(para => {
      if (para.trim()) {
        htmlContent += `<p>${para.trim()}</p>\n`;
      }
    });
  }
});

// Prepare data for API Template
return {
  json: {
    manuscriptTitle: manuscriptData.title || webhookData.manuscriptTitle,
    authorName: authorData?.first_name && authorData?.last_name 
      ? `${authorData.first_name} ${authorData.last_name}` 
      : webhookData.authorFirstName || 'Author',
    phaseNumber: webhookData.phaseNumber,
    editorName: webhookData.editorName,
    completionDate: new Date().toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    }),
    manuscriptContent: htmlContent
  }
};

// After uploading to Supabase Storage, build the public URL
const webhookData = $('Webhook').first().json.body;
const uploadResponse = $json;

// Build the public URL for the uploaded file
const filename = `${webhookData.manuscriptId}_phase${webhookData.phaseNumber}_approved.pdf`;
const publicUrl = `https://itlkncjiifbgvmvuejgm.supabase.co/storage/v1/object/public/manuscript-versions/${filename}`;

console.log('✅ File uploaded, public URL:', publicUrl);

return {
  json: {
    fileUrl: publicUrl,
    manuscriptId: webhookData.manuscriptId,
    phaseNumber: webhookData.phaseNumber
  }
};

